  "grammar-ex:N3:uto-shita:7": "/audio/grammar-examples/N3/uto-shita_7.opus",
  "彼は突然、私を殴ろうとした。": "/audio/grammar-examples/N3/uto-shita_7.opus",
  "grammar-ex:N3:okagede:0": "/audio/grammar-examples/N3/okagede_0.opus",
  "grammar-ex:N3:okagede:1": "/audio/grammar-examples/N3/okagede_1.opus",
